import { remark } from 'remark'

type Node = { type: string; url?: string; children?: Node[] }
const pathPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\/[a-zA-Z0-9._-]+$/

// Require the exact spelling generated by the uploader, not a URL containing it.
export function publishedAssetPaths(draft: unknown): string[] {
  if (!draft || typeof draft !== 'object') return []
  const content = draft as Record<string, unknown>
  const paths = new Set<string>()
  function collect(value: unknown) {
    if (typeof value !== 'string' || !value.startsWith('/api/archive/asset?path=')) return
    try {
      const path = decodeURIComponent(value.slice('/api/archive/asset?path='.length))
      if (pathPattern.test(path) && value === `/api/archive/asset?path=${encodeURIComponent(path)}`)
        paths.add(path)
    } catch {
      /* malformed URL */
    }
  }
  for (const field of ['coverImage', 'url', 'slidesUrl', 'videoUrl']) collect(content[field])
  function walk(node: Node) {
    if (['link', 'image', 'definition'].includes(node.type)) collect(node.url)
    node.children?.forEach(walk)
  }
  if (typeof content.body === 'string') walk(remark().parse(content.body) as Node)
  return [...paths]
}
